//! `GET /api/sitemap.xml` (sitemaps.org protocol 0.9): the public pages of the portal and every
//! published idea, so that search engines find ideas without running the single-page app.
//!
//! Referenced by the `Sitemap:` line of `/robots.txt` (generated by the frontend container from
//! `TRAEFIK_HOST`), which lets it list URLs outside `/api/`. Only published ideas appear (never a
//! hidden, withdrawn, merged or rejected text), each with the day of its current analysis.

use axum::extract::State;
use axum::http::{HeaderValue, StatusCode, header};
use axum::response::{IntoResponse, Response};
use chrono::NaiveDate;

use super::AppState;
use super::cache;
use super::error::ApiError;
use super::ideas::public_host;
use crate::db::portal::{self, SitemapIdea};
use crate::domain::rules::LEGAL_PAGES_UPDATED_ON;
use crate::domain::slug::is_valid_slug;
use crate::jobs::exports::canonical_url;

const CONTENT_TYPE: HeaderValue = HeaderValue::from_static("application/xml; charset=utf-8");

/// A page of the portal: path, last modification (`YYYY-MM-DD`) when known, priority.
struct StaticPage {
    path: &'static str,
    lastmod: Option<&'static str>,
    priority: &'static str,
}

/// Public pages of the portal (`frontend/src/app/paths.ts`), the tracking page and the
/// administration excluded.
const STATIC_PAGES: &[StaticPage] = &[
    StaticPage {
        path: "/proposer",
        lastmod: None,
        priority: "0.8",
    },
    StaticPage {
        path: "/methodologie",
        lastmod: None,
        priority: "0.6",
    },
    StaticPage {
        path: "/a-propos",
        lastmod: None,
        priority: "0.5",
    },
    StaticPage {
        path: "/regles",
        lastmod: Some(LEGAL_PAGES_UPDATED_ON.regles),
        priority: "0.3",
    },
    StaticPage {
        path: "/licence",
        lastmod: Some(LEGAL_PAGES_UPDATED_ON.licence),
        priority: "0.3",
    },
    StaticPage {
        path: "/mentions-legales",
        lastmod: Some(LEGAL_PAGES_UPDATED_ON.mentions_legales),
        priority: "0.2",
    },
    StaticPage {
        path: "/confidentialite",
        lastmod: Some(LEGAL_PAGES_UPDATED_ON.confidentialite),
        priority: "0.2",
    },
];

#[utoipa::path(
    get,
    path = "/api/sitemap.xml",
    tag = "reference",
    operation_id = "getSitemap",
    responses(
        (status = 200, description = "Plan du site (protocole sitemaps.org) : pages publiques et idées publiées.",
         content_type = "application/xml", body = String)
    )
)]
pub async fn sitemap(State(state): State<AppState>) -> Result<Response, ApiError> {
    let ideas = portal::sitemap_ideas(&state.pool).await?;
    let body = render(public_host(&state), &ideas);
    let mut response = (StatusCode::OK, body).into_response();
    response
        .headers_mut()
        .insert(header::CONTENT_TYPE, CONTENT_TYPE);
    Ok(cache::with_cache_control(response, cache::MEDIUM))
}

/// The sitemap document. The home page is dated by the most recent analysis.
fn render(host: &str, ideas: &[SitemapIdea]) -> String {
    let base = format!("https://{host}");
    let ideas: Vec<&SitemapIdea> = ideas.iter().filter(|i| is_valid_slug(&i.slug)).collect();
    let latest: Option<NaiveDate> = ideas.iter().map(|i| i.updated_on).max();
    let mut xml = String::with_capacity(256 + ideas.len() * 160);
    xml.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    xml.push_str("<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n");
    let home_lastmod = latest.map(day);
    push_url(
        &mut xml,
        &format!("{base}/"),
        home_lastmod.as_deref(),
        "1.0",
    );
    for page in STATIC_PAGES {
        push_url(
            &mut xml,
            &format!("{base}{}", page.path),
            page.lastmod,
            page.priority,
        );
    }
    for idea in ideas {
        let lastmod = day(idea.updated_on);
        push_url(
            &mut xml,
            &canonical_url(host, &idea.slug),
            Some(&lastmod),
            "0.7",
        );
    }
    xml.push_str("</urlset>\n");
    xml
}

fn day(date: NaiveDate) -> String {
    date.format("%Y-%m-%d").to_string()
}

fn push_url(xml: &mut String, loc: &str, lastmod: Option<&str>, priority: &str) {
    xml.push_str("  <url>\n    <loc>");
    xml.push_str(&escape(loc));
    xml.push_str("</loc>\n");
    if let Some(lastmod) = lastmod {
        xml.push_str("    <lastmod>");
        xml.push_str(&escape(lastmod));
        xml.push_str("</lastmod>\n");
    }
    xml.push_str("    <priority>");
    xml.push_str(priority);
    xml.push_str("</priority>\n  </url>\n");
}

/// XML text escaping (the host comes from the configuration, slugs are validated).
fn escape(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&apos;"),
            _ => out.push(c),
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn idea(slug: &str, day: &str) -> SitemapIdea {
        SitemapIdea {
            slug: slug.to_owned(),
            updated_on: NaiveDate::parse_from_str(day, "%Y-%m-%d").unwrap(),
        }
    }

    #[test]
    fn lists_static_pages_and_ideas() {
        let xml = render(
            "iapolitique.fr",
            &[
                idea("une-idee", "2026-10-20"),
                idea("autre-idee", "2026-11-01"),
            ],
        );
        assert!(xml.starts_with("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset"));
        assert!(
            xml.contains("<loc>https://iapolitique.fr/</loc>\n    <lastmod>2026-11-01</lastmod>")
        );
        assert!(xml.contains(
            "<loc>https://iapolitique.fr/idees/une-idee</loc>\n    <lastmod>2026-10-20</lastmod>"
        ));
        assert!(xml.contains("<loc>https://iapolitique.fr/methodologie</loc>"));
        assert!(xml.contains("<loc>https://iapolitique.fr/regles</loc>"));
        assert!(!xml.contains("/suivi"));
        assert!(!xml.contains("/admin"));
        assert_eq!(xml.matches("<url>").count(), 1 + STATIC_PAGES.len() + 2);
        assert!(xml.ends_with("</urlset>\n"));
    }

    #[test]
    fn home_has_no_date_without_ideas_and_invalid_slugs_are_skipped() {
        let xml = render("iapolitique.fr", &[idea("Pas<un>slug", "2026-10-20")]);
        assert!(xml.contains("<loc>https://iapolitique.fr/</loc>\n    <priority>"));
        assert!(!xml.contains("Pas"));
        assert!(!xml.contains("/idees/"));
    }

    #[test]
    fn escapes_xml() {
        assert_eq!(escape("a&b<c>\"'"), "a&amp;b&lt;c&gt;&quot;&apos;");
    }
}
